<script setup lang="ts">
import {computed} from 'vue';
const props=defineProps<{modelValue?:Array<Record<string,unknown>>}>(); const emit=defineEmits<{ 'update:modelValue':[value:Array<Record<string,unknown>>] }>();
const stages=computed(()=>props.modelValue||[]); const add=()=>emit('update:modelValue',[...stages.value,{name:'',percentage:0,status:'待收款'}]); const update=(index:number,key:string,value:unknown)=>emit('update:modelValue',stages.value.map((item,i)=>i===index?{...item,[key]:value}:item)); const remove=(index:number)=>emit('update:modelValue',stages.value.filter((_,i)=>i!==index));
</script>
<template><div class="payment-stages"><div class="field-heading"><span>付款节点</span><button type="button" class="secondary" @click="add">新增节点</button></div><div v-for="(stage,index) in stages" :key="index" class="form-grid"><input :value="stage.name" placeholder="节点名称" @input="update(index,'name',($event.target as HTMLInputElement).value)"/><input :value="stage.percentage" type="number" min="0" max="100" placeholder="比例%" @input="update(index,'percentage',Number(($event.target as HTMLInputElement).value))"/><select :value="stage.status" @change="update(index,'status',($event.target as HTMLSelectElement).value)"><option value="待收款">待收款</option><option value="已收款">已收款</option></select><button type="button" class="secondary" @click="remove(index)">删除</button></div><small v-if="stages.length">比例合计：{{stages.reduce((sum,item)=>sum+Number(item.percentage||0),0)}}%</small></div></template>
